class Solution {
    public int minSwaps(int[] nums){
        int n=nums.length,ones=Arrays.stream(nums).sum();
        if(ones<=1)return 0;
        int window=0;
        for(int i=0;i<ones;i++)window+=nums[i%n];
        int maximum=window;
        for(int end=ones;end<ones+n;end++){
            window+=nums[end%n]-nums[(end-ones)%n];
            maximum=Math.max(maximum,window);
        }
        return ones-maximum;
    }
}

code.kotlin:
class Solution {
    fun minSwaps(nums:IntArray):Int{
        val n=nums.size;
        val ones=nums.sum();
        if(ones<=1)return 0;
        var window=0;
        for(i in 0 until ones)window+=nums[i%n];
        var maximum=window;
        for(end in ones until ones+n){
            window+=nums[end%n]-nums[(end-ones)%n];
            maximum=maxOf(maximum,window)
        };
        return ones-maximum
    }
}

